package ua.empirecraft.casting.test;
import java.util.*;import com.google.gson.*;
import net.minecraft.core.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.inventory.TransientCraftingContainer;import net.minecraft.world.SimpleContainer;import net.minecraft.world.level.block.Blocks;import net.minecraftforge.common.capabilities.ForgeCapabilities;import net.minecraftforge.items.*;import net.dries007.tfc.common.blockentities.*;import net.dries007.tfc.common.blocks.TFCBlocks;import net.dries007.tfc.common.blocks.DirectionPropertyBlock;import net.dries007.tfc.common.blocks.devices.*;import net.dries007.tfc.common.capabilities.heat.*;import net.dries007.tfc.util.Fuel;import net.dries007.tfc.common.recipes.*;import net.dries007.tfc.common.recipes.inventory.ItemStackInventory;import net.stirdrem.overgeared.recipe.ForgingRecipe;import ua.empirecraft.casting.*;import ua.empirecraft.casting.mixin.InventoryAccess;
public final class MetallurgyProbe {
 static int checks;static void check(boolean ok,String reason){checks++;if(!ok)throw new AssertionError(reason);}
 static ItemStack stack(String id){return new ItemStack(CastingProbe.item(id));}
 static Recipe<?> recipe(MinecraftServer server,String id){return server.getRecipeManager().byKey(new ResourceLocation(id)).orElseThrow(()->new AssertionError("Missing recipe "+id));}
 public static void check(MinecraftServer server,ServerLevel level)throws Exception{
  var config=net.dries007.tfc.config.TFCConfig.SERVER;check(config.blastFurnaceCapacity.get()==16,"Blast furnace per-level capacity is 16");
  var pos=new BlockPos(1900,100,1900);level.getChunkAt(pos);level.setBlockAndUpdate(pos,TFCBlocks.CRUCIBLE.get().defaultBlockState());var crucible=(CrucibleBlockEntity)level.getBlockEntity(pos);
  var top=crucible.getCapability(ForgeCapabilities.ITEM_HANDLER,Direction.UP).orElseThrow(()->new AssertionError("Crucible top input"));var side=crucible.getCapability(ForgeCapabilities.ITEM_HANDLER,Direction.NORTH).orElseThrow(()->new AssertionError("Crucible side input"));
  check(top.insertItem(0,stack("minecraft:raw_iron"),false).isEmpty(),"Top hopper accepts smelting input");check(side.insertItem(1,stack("minecraft:raw_copper"),false).isEmpty(),"Create side funnel accepts smelting input");check(top.extractItem(0,1,false).isEmpty()&&side.extractItem(1,1,false).isEmpty(),"Input ports cannot extract unprocessed ores");
  var forgePos=pos.offset(4,0,0);level.setBlockAndUpdate(forgePos,TFCBlocks.CHARCOAL_FORGE.get().defaultBlockState());var forge=(CharcoalForgeBlockEntity)level.getBlockEntity(forgePos);var inventory=((InventoryAccess)forge).casting$inventory();var coal=new ItemStack(Items.CHARCOAL,64);
  check(inventory.insertItem(0,coal,false).getCount()==48&&inventory.getStackInSlot(0).getCount()==16,"Forge fuel slot accepts exactly 16");check(inventory.getSlotLimit(5)==1,"Forge smelting input remains one item to prevent material loss");
  var consume=CharcoalForgeBlockEntity.class.getDeclaredMethod("consumeFuel");consume.setAccessible(true);check((boolean)consume.invoke(forge),"Forge lights using native fuel code");check(inventory.getStackInSlot(0).getCount()==15,"One burn consumes one charcoal, not the 16-stack");
  int duration=Fuel.get(new ItemStack(Items.CHARCOAL)).getDuration();var remainder=HeatCapability.consumeFuelForTicks(duration*2L+1,inventory,0,0,0,4);check(inventory.getStackInSlot(0).getCount()==12&&remainder.burnTicks()==duration-1,"Offline catch-up consumes three individual charcoal units");
  // Build one native chimney level with iron sheet insulation, then exercise actual capacity calculation.
  var furnacePos=pos.offset(12,0,0);level.setBlockAndUpdate(furnacePos,TFCBlocks.BLAST_FURNACE.get().defaultBlockState());var center=furnacePos.above();level.setBlockAndUpdate(center,Blocks.AIR.defaultBlockState());
  for(var d:Direction.Plane.HORIZONTAL)level.setBlockAndUpdate(center.relative(d),TFCBlocks.FIRE_BRICKS.get().defaultBlockState());
  for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)if((Math.abs(x)==2&&z==0)||(Math.abs(z)==2&&x==0)||(Math.abs(x)==1&&Math.abs(z)==1)){
   var sheetPos=center.offset(x,0,z);var state=TFCBlocks.SHEET_PILE.get().defaultBlockState();for(var d:Direction.Plane.HORIZONTAL)state=state.setValue(DirectionPropertyBlock.getProperty(d),true);level.setBlockAndUpdate(sheetPos,state);var pile=(SheetPileBlockEntity)level.getBlockEntity(sheetPos);for(var d:Direction.Plane.HORIZONTAL)pile.addSheet(d,stack("tfc:metal/sheet/wrought_iron"));
  }
  check(BlastFurnaceBlock.getChimneyLevels(level,furnacePos)==1,"Native single-block chimney is valid");var calculate=BlastFurnaceBlockEntity.class.getDeclaredMethod("calculateCapacity");calculate.setAccessible(true);check((int)calculate.invoke(level.getBlockEntity(furnacePos))==16,"Actual blast furnace capacity is 16 for one molten block");
  // Simulate a remote drafting client, whose server datapack reload listener is empty.
  var typeData=net.stirdrem.overgeared.datapack.BlueprintTooltypesReloadListener.DATA;
  var savedTypes=new java.util.HashMap<>(typeData);typeData.clear();
  try{net.stirdrem.overgeared.item.ToolTypeRegistry.init();for(String type:new String[]{"javelin_head","scythe_blade","pickaxe_head","axe_head","shovel_head","hoe_head","hammer_head","knife_blade","saw_blade","chisel_head"})check(net.stirdrem.overgeared.item.ToolTypeRegistry.getRegisteredTypes().stream().anyMatch(t->t.getId().equals(type)),"Part blueprint is selectable without server datapack data: "+type);}
  finally{typeData.putAll(savedTypes);net.stirdrem.overgeared.item.ToolTypeRegistry.init();}
  var data=JsonParser.parseReader(new java.io.InputStreamReader(Metallurgy.class.getResourceAsStream("/metallurgy.json"))).getAsJsonObject();
  for(var entry:data.getAsJsonObject("recipes").entrySet()){
   var actual=recipe(server,entry.getKey());var spec=entry.getValue().getAsJsonObject();if(!spec.get("type").getAsString().equals("overgeared:forging"))continue;
   check(actual instanceof ForgingRecipe,"Part/refining recipe uses real Overgeared forging");var forging=(ForgingRecipe)actual;var material=spec.getAsJsonObject("key").getAsJsonObject("I").getAsJsonObject("ingredient").get("item").getAsString();var ingredient=forging.getForgingIngredients().stream().filter(i->!i.ingredient().isEmpty()).findFirst().orElseThrow();var input=stack(material);
   check(!ingredient.test(input),"Cold metal is rejected: "+entry.getKey());check(HeatCapability.get(input)!=null,"Forge material has native TFC heat: "+material);HeatCapability.setTemperature(input,1400);check(ingredient.test(input),"Heated metal is accepted: "+entry.getKey());
   var anvilInput=new SimpleContainer(12);for(int y=0;y<forging.getHeight();y++)for(int x=0;x<forging.getWidth();x++)anvilInput.setItem(y*3+x,input.copy());
   if(forging.requiresBlueprint()){var blueprint=stack("overgeared:blueprint");blueprint.getOrCreateTag().putString("ToolType",spec.getAsJsonArray("blueprint").get(0).getAsString());blueprint.getOrCreateTag().putString("Quality","master");anvilInput.setItem(11,blueprint);}
   var selected=ForgingRecipe.findBestMatch(level,anvilInput);check(selected.isPresent()&&((Recipe<?>)selected.get()).getId().equals(actual.getId()),"The native anvil selects this exact part, not another one: "+entry.getKey());
  }
  var player=net.minecraftforge.common.util.FakePlayerFactory.get(level,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("f727e586-4ba0-497e-912b-180eb66ff663"),"MetallurgyProbe"));int weapons=0,tools=0;var conflicts=new java.util.ArrayList<String>();
  for(var entry:data.getAsJsonObject("recipes").entrySet()){
   var spec=entry.getValue().getAsJsonObject();if(!spec.get("type").getAsString().equals("empirecraft_casting:quality_shaped"))continue;
   var actual=recipe(server,entry.getKey());check(actual instanceof QualityRecipe,"Assembly uses native shaped recipe subclass");var grid=new TransientCraftingContainer(player.inventoryMenu,3,3);var pattern=spec.getAsJsonArray("pattern");var key=spec.getAsJsonObject("key");var sampleRecipe=(ShapedRecipe)actual;
   for(int row=0;row<sampleRecipe.getHeight();row++)for(int col=0;col<sampleRecipe.getWidth();col++){
    var ingredient=sampleRecipe.getIngredients().get(col+row*sampleRecipe.getWidth());if(ingredient.isEmpty())continue;check(ingredient.getItems().length>0,"Assembly ingredient exists");var input=ingredient.getItems()[0].copy();String id=ua.empirecraft.tfc.Integration.id(input.getItem());if(id.contains("_head/")||id.contains("_blade/")||id.endsWith("_javelin_head"))input.getOrCreateTag().putString("ForgingQuality","master");grid.setItem(row*3+col,input);
   }
   var selected=server.getRecipeManager().getRecipeFor(RecipeType.CRAFTING,grid,level);if(selected.isEmpty()||!selected.get().getId().equals(actual.getId()))conflicts.add(entry.getKey()+" selected "+selected.map(r->r.getId().toString()).orElse("none"));check(((ShapedRecipe)actual).matches(grid,level),"Native crafting grid matches assembly: "+entry.getKey());var result=((ShapedRecipe)actual).assemble(grid,server.registryAccess());check(result.hasTag()&&result.getTag().getString("ForgingQuality").equals("master"),"Master quality is preserved into the final equipment: "+entry.getKey());if(entry.getKey().contains("/tfc/"))tools++;else weapons++;
  }
  check(weapons>0&&tools>0,"Both Epic Knights and TFC tool assemblies are covered");
  var blast=BlastFurnaceRecipe.get(level,stack("minecraft:raw_iron"));check(blast!=null&&blast.assembleFluidOutput(CastingProbe.fluid("cast_iron",100)).isFluidEqual(CastingProbe.fluid("pig_iron",100)),"Raw iron enters the real blast-furnace route to pig iron");
  for(String material:new String[]{"gold","silver"}){var head=stack("empirecraft_casting:"+material+"_javelin_head");var melt=HeatingRecipe.getRecipe(head);check(HeatCapability.get(head)!=null&&melt!=null&&melt.assembleFluid(new ItemStackInventory(head)).isFluidEqual(CastingProbe.fluid(material,100)),"New spearheads retain their full metal value for remelting: "+material);}
  var high=stack("tfc:metal/ingot/high_carbon_steel");var heating=HeatingRecipe.getRecipe(high);check(heating!=null&&heating.assembleFluid(new ItemStackInventory(high)).isFluidEqual(CastingProbe.fluid("pig_iron",100)),"Legacy high-carbon steel recovers pig iron for flux refining");
  check(server.getRecipeManager().byKey(new ResourceLocation("empirecraft_tfc:refining/metal/ingot/high_carbon_steel")).isEmpty(),"Early heating-to-steel no longer masks the high-carbon liquid route");
  check(server.getRecipeManager().getRecipes().stream().noneMatch(r->r.getId().toString().equals("overgeared:crude_steel_from_alloying")),"Ordinary Overgeared iron/coal steel bypass is removed");
  for(var r:server.getRecipeManager().getRecipes()){String result=ua.empirecraft.tfc.Integration.id(r.getResultItem(server.registryAccess()).getItem());check(!Metallurgy.retired(result),"Removed metals have no remaining acquisition recipe: "+r.getId());}
  check(server.getRecipeManager().byKey(new ResourceLocation("empirecraft_casting:refining/high_carbon_steel")).isEmpty()&&server.getRecipeManager().byKey(new ResourceLocation("empirecraft_casting:refining/steel")).isEmpty(),"High-carbon steel forging stages are removed");recipe(server,"empirecraft_casting:refining/black_steel");recipe(server,"tfc:alloy/weak_steel");
  var weak=CastingProbe.pair();CastingProbe.mold(weak);CastingProbe.fill(weak,"steel",600);CastingProbe.fill(weak,"nickel",200);CastingProbe.fill(weak,"bronze",200);CastingProbe.heat(weak);check(weak.metal().drain(100,net.minecraftforge.fluids.capability.IFluidHandler.FluidAction.SIMULATE).isFluidEqual(CastingProbe.fluid("weak_steel",100)),"Actual 60/20/20 alloy yields weak steel without black bronze");CastingProbe.run(weak,CastingBlockEntity.CYCLE_TICKS);check(CastingProbe.out(weak).is(CastingProbe.item("tfc:metal/ingot/weak_steel")),"Weak steel is obtainable as a cast intermediate");
  var black=CastingProbe.pair();CastingProbe.mold(black);CastingProbe.fill(black,"weak_steel",100);CastingProbe.fill(black,"pig_iron",100);CastingProbe.heat(black);check(black.metal().drain(100,net.minecraftforge.fluids.capability.IFluidHandler.FluidAction.SIMULATE).isFluidEqual(CastingProbe.fluid("high_carbon_black_steel",100)),"Actual 50/50 alloy yields high-carbon black steel");CastingProbe.run(black,CastingBlockEntity.CYCLE_TICKS);check(CastingProbe.out(black).is(CastingProbe.item("tfc:metal/ingot/high_carbon_black_steel")),"High-carbon black steel can be cast for final refining");
  check(conflicts.isEmpty(),"Crafting manager selects every exact quality-preserving assembly: "+conflicts);
  System.out.println("CASTING_NATIVE_METALLURGY_PASS checks="+checks+" weapons="+weapons+" tools="+tools+" forge_stack=16 blast_level=16 hopper=passed quality=passed high_carbon=passed");
 }
}
